@prefix : <http://example.org/> .
@prefix skos: <http://www.w3.org/2004/02/skos/core#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix owl: <http://www.w3.org/2002/07/owl#> .
# (a) taxonomy
:CNN a skos:Concept ; skos:broader :NeuralNetwork .
:alexnet :instanceOf :CNN .
# (b) ontology
:CNN a owl:Class ; rdfs:subClassOf :NeuralNetwork .
:alexnet a :CNN .

@prefix : <http://example.org/> . @prefix owl: <http://www.w3.org/2002/07/owl#> . @prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
:Exam rdfs:subClassOf :Assessed . :Project rdfs:subClassOf :Assessed .
:Assessment rdfs:subClassOf [ a owl:Class ; owl:unionOf ( :Exam :Project ) ] .

@prefix ex: <http://example.org/> .
ex:g1 { ex:CNN4 ex:prerequisite ex:Convolution . }
ex:g2 { ex:CNN4 ex:prerequisite ex:Backprop . }
ex:meta { ex:g1 ex:source ex:SyllabusA . }

@prefix ex: <http://example.org/> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
ex:CNN4 a ex:Lecture ;
  rdfs:label "Convolutional Networks"@en ;
  ex:durationMin "90"^^xsd:integer ;
  ex:taughtBy [ a ex:Person ; ex:name "A. Teacher" ] .

:LectureShape a sh:NodeShape ; sh:targetClass :Lecture ;
  sh:property [ sh:path :covers ; sh:minCount 1 ; sh:class :Topic ; sh:message "A lecture must cover at least one Topic" ] ;
  sh:property [ sh:path :durationMin ; sh:datatype xsd:integer ; sh:maxCount 1 ] .
:Backprop a :Topic . :l1 a :Lecture ; :covers :Backprop ; :durationMin 90 .
:l2 a :Lecture . :l3 a :Lecture ; :covers :Bob ; :durationMin "ninety" .
